23|pub struct Selector {
24|    pub in_: Vec<KeyDepth>,
25|    pub in_any: Vec<KeyDepth>,
26|    pub not_in: Vec<KeyDepth>,
27|    pub max_depth: Option<u8>,
28|}
29|
30|impl Selector {
31|    pub fn is_empty(&self) -> bool {
32|        self.in_.is_empty()
33|            && self.in_any.is_empty()
34|            && self.not_in.is_empty()
35|            && self.max_depth.is_none()
36|    }
37|
38|    pub fn resolve(&self, graph: &Graph) -> HashSet<Key> {
39|        let mut candidates: Option<HashSet<Key>> = None;
40|
41|        for kd in &self.in_ {
42|            let depth = kd.depth.or(self.max_depth);
43|            let set = descendants_at_depth(graph, &kd.key, depth);
44|            candidates = Some(match candidates {
45|                None => set,
46|                Some(c) => c.intersection(&set).cloned().collect(),
47|            });
48|        }
49|
50|        if !self.in_any.is_empty() {
51|            let mut union: HashSet<Key> = HashSet::new();
52|            for kd in &self.in_any {
53|                let depth = kd.depth.or(self.max_depth);
54|                union.extend(descendants_at_depth(graph, &kd.key, depth));
55|            }
56|            candidates = Some(match candidates {
57|                None => union,
58|                Some(c) => c.intersection(&union).cloned().collect(),
59|            });
60|        }
61|
62|        let mut result =
63|            candidates.unwrap_or_else(|| graph.keys().into_iter().collect());
64|
65|        for kd in &self.not_in {
66|            let depth = kd.depth.or(self.max_depth);
67|            let exclude = descendants_at_depth(graph, &kd.key, depth);
68|            result = result.difference(&exclude).cloned().collect();
69|        }
70|
71|        result
72|    }
73|}
74|
75|pub fn descendants_at_depth(graph: &Graph, origin: &Key, depth: Option<u8>) -> HashSet<Key> {
76|    let mut result: HashSet<Key> = HashSet::new();
77|    let mut frontier: Vec<Key> = vec![origin.clone()];
78|    let mut walked: u8 = 0;
79|
80|    loop {
81|        if let Some(d) = depth {
82|            if walked >= d {
83|                break;
84|            }
85|        }
86|
87|        let mut next: Vec<Key> = Vec::new();
88|        for current in &frontier {
89|            for ref_id in graph.get_block_references_in(current) {
90|                if let Some(ref_key) = graph.graph_node(ref_id).ref_key() {
91|                    if &ref_key == origin {
92|                        continue;
93|                    }
94|                    if result.insert(ref_key.clone()) {
95|                        next.push(ref_key);
96|                    }
97|                }
98|            }
99|        }
100|
101|        if next.is_empty() {
102|            break;
103|        }
104|        frontier = next;
105|        walked = walked.saturating_add(1);
106|    }
107|
108|    result
109|}
